def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    serious_bids = []
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                if bid >= 40:
                    serious_bids.append(bid)

    if not alive:
        return float(min(budget, 8.0))

    high_prev = max(serious_bids) if serious_bids else 0.0
    low_prev = min(serious_bids) if serious_bids else 0.0

    units = supply / WATER_REQ
    very_tight = units < 1.4
    tight = units < 1.8

    if hp <= 2 or no_water >= 2:
        target = max(95.0, high_prev + 3.0)
    elif hp <= 4 or no_water >= 1:
        if high_prev > 0:
            target = high_prev + 2.0
        else:
            target = 72.0
    else:
        if very_tight:
            if high_prev >= 150:
                target = 108.0
            elif high_prev >= 110:
                target = high_prev + 1.5
            elif high_prev > 0:
                target = max(82.0, high_prev + 2.0)
            else:
                target = 78.0
        elif tight:
            if high_prev >= 140:
                target = 92.0
            elif high_prev > 0:
                target = max(68.0, low_prev + 2.0)
            else:
                target = 60.0
        else:
            if desperate_count >= 2:
                target = 66.0
            elif high_prev > 0:
                target = max(52.0, low_prev + 1.0)
            else:
                target = 45.0

    if budget < DAILY_SALARY * 1.2:
        target = min(target, budget * 0.72)
    elif budget < DAILY_SALARY * 2.0 and hp > 4 and no_water == 0:
        target = min(target, DAILY_SALARY * 0.95)

    if hp >= 7 and no_water == 0 and high_prev >= 170 and very_tight:
        target = min(target, 88.0)

    bid = max(0.0, min(float(budget), float(target)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((opp_id, o))

    # If no opponents alive, conserve budget.
    if not alive_opps:
        cap = DAILY_SALARY * 0.4
        return min(my_budget, cap)

    # Read yesterday's bid pressure from previous_trace only.
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Determine how urgent we are.
    # If we've already gone multiple days without water or very low HP, bid aggressively.
    urgent = (my_hp <= 2) or (my_no_water_days >= 2)

    # Supply-based base bid: higher supply -> can bid slightly less.
    # Map supply in [15,25] to a multiplier in [1.05,0.85].
    if MAX_SUPPLY != MIN_SUPPLY:
        t = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
    else:
        t = 0.5
    t = max(0.0, min(1.0, float(t)))
    supply_mult = 1.05 - 0.20 * t

    # If others were bidding very high yesterday, undercut with a fraction.
    # Cindy/Alex were ~126-152 avg; avoid matching their max (~189).
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if urgent:
            target = highest_prev_bid * 0.78
        else:
            target = highest_prev_bid * 0.62
    else:
        # If pressure was low, bid to secure without overpaying.
        if urgent:
            target = max(DAILY_SALARY * 0.75, highest_prev_bid * 0.8)
        else:
            target = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.55)

    target *= supply_mult

    # Also ensure we don't bid too low when our water need is high relative to supply.
    # Approximate how many water units might be contested: higher supply reduces need.
    # Use a conservative floor based on supply/WATER_REQ.
    units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 1
    if units <= 1:
        target *= 1.10

    # Final bounds: cannot exceed budget.
    # Keep a minimum bid fraction so we don't get starved when others are active.
    min_bid = DAILY_SALARY * (0.35 if not urgent else 0.65)
    bid = max(min_bid, target)

    return min(my_budget, bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    # Get yesterday's bids from previous_trace
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine urgency: need water if HP low or no_water_days > 0
    urgent = (my_status['hp'] <= 2) or (my_status['no_water_days'] > 0)

    # Base bid
    base_bid = DAILY_SALARY * 0.7  # 98

    if yesterday_bids:
        max_yesterday = max(yesterday_bids)
        if urgent:
            # Need to win: slightly above yesterday's max, but cap by budget
            bid = min(my_status['budget'], max_yesterday + 2.0)
        else:
            # Try to save: bid just below yesterday's max if we can afford to lose, else base
            if my_status['hp'] > 6:
                bid = min(my_status['budget'], max(0.0, max_yesterday - 5.0))
            else:
                bid = min(my_status['budget'], base_bid)
    else:
        # No yesterday info, use baseline
        bid = base_bid if not urgent else min(my_status['budget'], DAILY_SALARY * 0.9)

    # Ensure we never bid more than budget
    bid = max(0.0, min(my_status['budget'], bid))
    # Also consider supply: if very low supply, bid higher to guarantee water
    supply = day_context['supply']
    if supply < 20 and urgent:
        bid = max(bid, min(my_status['budget'], DAILY_SALARY * 0.95))
    # Keep budget for future days: never spend more than 80% of budget if not urgent and early days?
    day = int(day_context['day'])
    if day <= 3 and not urgent:
        bid = min(bid, DAILY_SALARY * 0.6)
    return float(bid)
